import os, subprocess, time

def format_size(size_bytes):
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024.0:
            return f'{size_bytes:.2f} {unit}'
        size_bytes /= 1024.0
    return f'{size_bytes:.2f} PB'

def get_props(target_path):
    is_dir = os.path.isdir(target_path)
    name = os.path.basename(target_path) or target_path
    stat_res = os.stat(target_path)
    mtime_str = time.strftime('%Y-%m-%d %I:%M %p', time.localtime(stat_res.st_mtime))
    if not is_dir:
        return {'name': name, 'size': format_size(stat_res.st_size), 'files': 1, 'folders': 0}
    try:
        size_out = subprocess.check_output(['du', '-sb', target_path], timeout=3.0).decode()
        size = int(size_out.split()[0])
    except Exception:
        size = 0
    try:
        f_out = subprocess.check_output(['find', target_path, '-type', 'f', '-printf', '.'], timeout=3.0).decode()
        files = f_out.count('.')
        d_out = subprocess.check_output(['find', target_path, '-type', 'd', '-printf', '.'], timeout=3.0).decode()
        folders = max(0, d_out.count('.') - 1)
    except Exception:
        files, folders = 0, 0
    return {'name': name, 'size': format_size(size), 'bytes': f'{size:,}', 'files': files, 'folders': folders, 'mtime': mtime_str}

