import os, subprocess, time

def get_folder_properties(target_path, timeout_sec=4.0):
    t0 = time.time()
    size_bytes = 0
    file_count = 0
    folder_count = 0

    # 1. Size via du -sb (fastest on Linux ext4/xfs)
    try:
        res = subprocess.run(['du', '-sb', target_path], capture_output=True, text=True, timeout=timeout_sec)
        if res.returncode == 0 and res.stdout:
            size_bytes = int(res.stdout.split()[0])
    except subprocess.TimeoutExpired:
        size_bytes = None
    except Exception as e:
        print('du error:', e)

    # 2. File and folder counts via find
    try:
        res_f = subprocess.run(['find', target_path, '-type', 'f', '-printf', '.'], capture_output=True, text=True, timeout=timeout_sec)
        if res_f.returncode == 0:
            file_count = len(res_f.stdout)
    except subprocess.TimeoutExpired:
        file_count = None
    except Exception as e:
        print('find file error:', e)

    try:
        res_d = subprocess.run(['find', target_path, '-mindepth', '1', '-type', 'd', '-printf', '.'], capture_output=True, text=True, timeout=timeout_sec)
        if res_d.returncode == 0:
            folder_count = len(res_d.stdout)
    except subprocess.TimeoutExpired:
        folder_count = None
    except Exception as e:
        print('find dir error:', e)

    t1 = time.time()
    print(f'Time: {t1-t0:.3f}s, size: {size_bytes}, files: {file_count}, folders: {folder_count}')

