            ['find', target_path, '-mindepth', '1', '-printf', '%s %y\n'],
            capture_output=True, text=True, timeout=timeout
        )
        lines = p.stdout.splitlines()
        total_bytes = 0
        files_count = 0
        folders_count = 0
