                        total_bytes += int(sz)
                    except:
                        pass
                    files_count += 1
                else:
                    folders_count += 1

        t1 = time.time()
        return {
            'success': True,
            'time': round(t1 - t0, 3),
            'size_bytes': total_bytes,
            'size_str': format_size(total_bytes),
