"async function fetchHistory() {
  try {
    const res = await fetch(`/api/history?range=${currentRange}`);
    if (!res.ok) return;
    historyData = await res.json();
    if (chartInstance) {
      chartInstance.data.labels = historyData.map(p => p.t);
      chartInstance.data.datasets = getDatasetsForCurrentMode();
      applyMonitorScales();
      chartInstance.update('none');
    } else {
      renderChart();
    }
    if (!isScrubbing && historyData && historyData.length > 0) {
      updateGraphReport(historyData[historyData.length - 1], false);
    }
  } catch (e) {
    console.error(e);
  }
}

function updateChartDatasets() {
  if (!chartInstance) {
    renderChart();
    return;
  }
  const datasets = getDatasetsForCurrentMode();
  chartInstance.data.labels = historyData.map(p => p.t);
  chartInstance.data.datasets = datasets;
  applyMonitorScales();
  chartInstance.update('none');
}"

