          <span>২য় · RAM: <span style="font-weight:600; color:var(--accent-blue);">${p.ram_mb >= 1024 ? (p.ram_mb/1024).toFixed(2) + ' GB' : p.ram_mb + ' MB'}</span></span>
        </div>
      </div>
    `).join('');
  }

  // Periodic Loops
  setInterval(fetchStats, 1500);
  setInterval(() => {
    if (activeTab === 'monitor' && !isScrubbing) {
      fetchHistory();
    }
  }, 30000);

  // Initial Startup
  window.addEventListener('DOMContentLoaded', () => {
    openThisPC();
    fetchStats();
    fetchHistory();
  });
</script>

</body>
</html>
